const separateParenGroups = (paren_string) => {
  const cleaned = paren_string.replace(/\s+/g, '');
  const result = [];
  let current = '';
  let depth = 0;

  for (const char of cleaned) {
    current += char;
    if (char === '(') {
      depth++;
    } else if (char === ')') {
      depth--;
    }

    if (depth === 0 && current.length > 0) {
      result.push(current);
      current = '';
    }
  }

  return result;
};

