const meanAbsoluteDeviation = (numbers) => {
  if (numbers.length === 0) return 0;
  const sum = numbers.reduce((acc, val) => acc + val, 0);
  const mean = sum / numbers.length;
  const absoluteDifferences = numbers.map((num) => Math.abs(num - mean));
  const sumAbsoluteDifferences = absoluteDifferences.reduce((acc, val) => acc + val, 0);
  return sumAbsoluteDifferences / numbers.length;
};

